                cin&gt;&gt;temp;
                array[temp]++;
        }

        //获取出现次数的最大值 
        int maxtime=0;
        for(int i=0;i&lt;1001;i++){
                if(array[i]&gt;maxtime){
                        maxtime=array[i];
                }
        }
        //从出现次数最大值开始输出，出现次数相同时按照从小到大输出 
        while(maxtime&gt;0){
                for(int i=0;i&lt;1001;i++){
                        if(array[i]==maxtime){
                                cout&lt;&lt;i&lt;&lt;" "&lt;&lt;maxtime&lt;&lt;endl;
                        }
                }
                maxtime--;
        }
        return 0;
}
