//201604-2                错误想法：先把落下的部分放到正确的位置，然后每个方块每次下落一，直到有方块的下方有东西为止
//正确思路：扫描每一列，计算下落距离。总的下落距离为每一列的最小值 
#include &lt;iostream&gt;
#include&lt;cmath&gt;
using namespace std;
const int row=15;
const int col=10;
int map[row][col];
int object[4][4];
int position;
int main(int argc, char** argv){
        //输入地图 
        for(int i=0;i&lt;row;i++){
                for(int j=0;j&lt;col;j++){
                        cin&gt;&gt;map[i][j];
                }
        } 
        //输入图形 
        for(int i=0;i&lt;4;i++){
                for(int j=0;j&lt;4;j++){
                        cin&gt;&gt;object[i][j];
                }
        }
        //输入开始的列数 
        cin&gt;&gt;position;
        position--;

        int down=row;//最大下落距离 

        for(int j=0;j&lt;4;j++){ //扫描每一列，计算下落距离 
                int t=0;
                int i;
                for(i=3;i&gt;=0;i--){//从下往上扫描要下落的图形 
                        if(object[i][j]==0){//统计这一列0的个数 
                                t++;
                        }
                        else
                                break;//出现非0就跳出 
                }
                if(i&lt;0){//i小于0代表本次扫描这一列全为0，即这一列没有图形 
                        continue;
                }
                //这一列有图形 ，去地图中扫描，计算下落距离 
                for(i=4;i&lt;row;i++){//前四行为0，不用扫描 
                        if(map[i][position+j]==0){//从上到下统计地图中这一列0的个数 
                                t++;
                        }
                        else{//出现非0时跳出循环 
                                break;
                        } 
                }
                down=min(down,t);//每次都取最小值，整个循环结束后，就是物体可以下落的值         
        }
        for(int i=0;i&lt;4;i++){//一行一行 
                if(i+down&gt;=row){//当下落高度超过限制，就结束循环 
                        break;
                }
                for(int j=0;j&lt;4;j++){
                        if(object[i][j]==1){
                                map[i+down][j+position]=1;
                        }
                }
        } 
        for(int i=0;i&lt;row;i++){
                for(int j=0;j&lt;col;j++){
                        cout&lt;&lt;map[i][j]&lt;&lt;" ";
                }
                cout&lt;&lt;endl;
        } 

        return 0;
}
